from typing import Any, Dict, List, Literal, Optional
from pydantic import BaseModel, ConfigDict, Field

from backend.app.schemas.transaction import ChangePlanItemCreate, PlanType


AssistantTargetType = Literal["file", "folder", "analysis", "plan", "general"]


class AssistantActionProposal(BaseModel):
    """A safe, structured action proposal generated by the assistant."""
    proposal_id: str = Field(..., description="Unique proposal identifier")
    title: str = Field(..., description="Short title of the proposed plan")
    description: str = Field(..., description="Clear explanation of what this proposal does and why")
    plan_type: PlanType = Field(default=PlanType.ORGANIZE, description="Plan type: organize, rename, or cleanup")
    items: List[ChangePlanItemCreate] = Field(default_factory=list, description="Structured operations to be reviewed")

    model_config = ConfigDict(from_attributes=True)


class AssistantExplainRequest(BaseModel):
    """Request to explain a selected entity within a Managed Folder context."""
    managed_folder_id: str = Field(..., description="ID of the active Managed Folder")
    target_type: AssistantTargetType = Field(..., description="Type of entity being explained")
    relative_path: Optional[str] = Field(None, description="Relative path within the managed folder for file/folder")
    entity_id: Optional[str] = Field(None, description="Identifier for plan or analysis target")
    user_query: Optional[str] = Field(None, description="Optional custom user query or question")

    model_config = ConfigDict(from_attributes=True)


class AssistantExplainResponse(BaseModel):
    """Contextual explanation and insights returned by the assistant."""
    managed_folder_id: str
    target_type: AssistantTargetType
    target_name: str
    relative_path: Optional[str] = None
    title: str
    summary: str
    key_insights: List[str] = Field(default_factory=list)
    metadata: Dict[str, Any] = Field(default_factory=dict)
    safety_assessment: str
    suggested_actions: List[AssistantActionProposal] = Field(default_factory=list)
    timestamp: str

    model_config = ConfigDict(from_attributes=True)


class AssistantSuggestPlanRequest(BaseModel):
    """Request to convert an assistant recommendation into a draft Change Plan in Review Changes."""
    managed_folder_id: str = Field(..., description="Target Managed Folder ID")
    title: str = Field(..., description="Title for the draft Change Plan")
    plan_type: PlanType = Field(default=PlanType.ORGANIZE, description="Plan type")
    items: List[ChangePlanItemCreate] = Field(..., min_length=1, description="Operations to include in the plan")

    model_config = ConfigDict(from_attributes=True)


class AssistantSuggestPlanResponse(BaseModel):
    """Response after creating a draft Change Plan routed to Review Changes."""
    plan_id: str
    title: str
    plan_type: str
    status: str = Field(default="pending_review", description="Status is always pending_review for AI proposals")
    items_count: int
    message: str
    created_at: str

    model_config = ConfigDict(from_attributes=True)


class QuickPromptItem(BaseModel):
    """Pre-canned contextual prompt suggestion."""
    label: str
    prompt: str
    target_type: AssistantTargetType

    model_config = ConfigDict(from_attributes=True)

